sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }

    var city = g_form.getValue('city');
    var state = g_form.getValue('state');

    if (!city || !state) {
        return;
    }

    var currentSysId = g_form.getUniqueValue();

    var ga = new GlideAjax('BranchUtils');
    ga.addParam('sysparm_name', 'checkDuplicateLocation');
    ga.addParam('sysparm_city', city);
    ga.addParam('sysparm_state', state);
    ga.addParam('sysparm_current', currentSysId);

    ga.getXMLAnswer(function(response) {
        if (response === 'true') {
            alert('A branch already exists for this city and state.');
            g_form.clearValue(control.name);
        }
    });
}
